#!/bin/bash
# Concatenates $VASP_PP_PATH/potpaw_PBE/<name>/POTCAR in the order of potcar.spec to make POTCAR (generated by ADIT)
# Concatenates the POTCARs listed in potcar.spec, in that order, into one POTCAR (generated by ADIT)
set -e
cd "$(dirname "$0")"
: "${VASP_PP_PATH:?VASP_PP_PATH is empty: set it to the parent directory of the POTCAR library first}"
: > POTCAR
: > potcar.used
for name in Si; do
  f="$VASP_PP_PATH/potpaw_PBE/$name/POTCAR"
  [ -s "$f" ] || { echo "no POTCAR at: $f" >&2; exit 1; }
  cat "$f" >> POTCAR
  printf '%s  %s  %s\n' "$name" "$(grep -m1 TITEL "$f" | sed 's/^ *//')" "$(grep -m1 ZVAL "$f" | sed 's/^ *//')" >> potcar.used
done
if command -v sha256sum >/dev/null 2>&1; then
  sha256sum POTCAR > potcar.sha256  # record at creation: SHA-256 of the assembled POTCAR (a hash for checking the contents; POTCAR itself cannot be distributed, so only the value is kept)
fi
echo "wrote POTCAR ($(grep -c TITEL POTCAR) entries; see potcar.used)"
